using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SandsOfTimeEffect", menuName = "Data/Battle/Effects/Sothis/SandsOfTime Effect")]
public class SandsOfTimeEffect : Effect
{
	private const string nonHexDieID = "NonHexDie";

	[Header("Lose Sands Of Time")]
	[SerializeField]
	private int loseSandsOfTimeOnActivationAmount;

	[SerializeField]
	private int minSandsOfTimeAmount;

	[Header("Auto Rewind Effect")]
	[SerializeField]
	private HourglassMasteryEffect hourglassMasteryEffect;

	[Header("Precision Action Workaround")]
	[SerializeField]
	private PrecisionAction precisionAction;

	[NonSerialized]
	[ShowNonSerializedField]
	private bool sandsOfTimeTriggered;

	[NonSerialized]
	[ShowNonSerializedField]
	private bool hourglassMasteryTriggered;

	[NonSerialized]
	[ShowNonSerializedField]
	public bool PrecisionActionPlayed;

	public HourglassMasteryEffect HourglassMasteryEffect => hourglassMasteryEffect;

	public bool SandsOfTimeTriggered => sandsOfTimeTriggered;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return FormattedDescriptionReplacedWithX(GetSandsOfTimeDescription(GetNumberToReplaceWithX()));
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return GetSandsOfTimeDescription(amount);
	}

	private string GetSandsOfTimeDescription(int amount)
	{
		string text = Smart.Format(GetLocalizedDescription(), amount, base.localizationManager.GetLocalizedThenDecreaseEffect(this, loseSandsOfTimeOnActivationAmount), minSandsOfTimeAmount, base.MaxEffectAmount);
		return Smart.Format(base.localizationManager.GetLocalizedWheneverYouPlayA(), base.localizationManager.GetLocalizedString("NonHexDie")) + base.localizationManager.GetLocalizedSpace() + text;
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		PrecisionActionPlayed = false;
	}

	public void ResetVariablesBeforeCheckSandsOfTime()
	{
		sandsOfTimeTriggered = false;
		hourglassMasteryTriggered = false;
	}

	public void CheckSandsOfTime(int chanceAmount, UnitEffects unitEffects)
	{
		if (chanceAmount < 100 && unitEffects.IsEffectActive(hourglassMasteryEffect, activateFeedback: false))
		{
			hourglassMasteryTriggered = true;
			chanceAmount = 100;
		}
		if (RandomUtilities.RandomChance(Mathf.Min(chanceAmount, 100)))
		{
			sandsOfTimeTriggered = true;
		}
	}

	public bool IsSandsOfTimeTriggeredTriggerIt(DiceInstance diceInstance, UnitEffects unitEffects)
	{
		if (!sandsOfTimeTriggered)
		{
			return false;
		}
		if (!hourglassMasteryTriggered)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 2f, delegate
			{
				if (diceInstance.DiceOwnerEnum == DiceOwnerEnum.COMPANION)
				{
					ReferenceSingleton<SothisOmensHandler>.Instance.ActivateHourglassModuleAction();
				}
				bool flag = false;
				if (ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance is DiceInstance)
				{
					ActionInstance lateCurrentActionInstance = ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance;
					if (lateCurrentActionInstance != null && lateCurrentActionInstance.ActionFace.BattleAction is RewindChantingAction)
					{
						flag = true;
					}
				}
				if (!flag)
				{
					int num = unitEffects.IsEffectActiveGetAmount(this);
					int num2 = loseSandsOfTimeOnActivationAmount;
					if (num - loseSandsOfTimeOnActivationAmount < minSandsOfTimeAmount)
					{
						num2 = num - minSandsOfTimeAmount;
					}
					if (num2 > 0)
					{
						unitEffects.IsEffectActiveAndDecreaseEffect(this, num2);
					}
				}
				else
				{
					unitEffects.IsEffectActive(this);
				}
			});
		}
		else
		{
			unitEffects.IsEffectActiveAndDecreaseEffect(hourglassMasteryEffect, 1);
		}
		SpriteControl component = unitEffects.GetComponent<SpriteControl>();
		component.PlayAnimationForced(AnimationType.Skill, AnimationChangeType.ReturnToIdleAnimation);
		if (component.HasAnimation(AnimationType.Skill))
		{
			PlayEffectActivationSFX();
			SpawnSecondVFXOnPlayerPosition(4f);
		}
		ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().OnRerollEffects(1);
		List<DiceInstance> list = new List<DiceInstance>();
		list.Add(diceInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.ActivateRerollOmens(list);
		RollDie(diceInstance);
		ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
		return true;
	}

	private void RollDie(DiceInstance diceInstance)
	{
		Action action = delegate
		{
			ReferenceSingleton<DiceRollingHandler>.Instance.RollDieWithDieSetup(new List<DiceInstance> { diceInstance });
		};
		if (!PrecisionActionPlayed)
		{
			action();
		}
		else
		{
			precisionAction.SandsOfTimePrecisionAction = action;
		}
	}
}
